import re
import six
from pyparsing import Regex, Literal, Optional, OneOrMore, Empty, ParseException, Group, Or as Or_
from re import match
from abc import abstractmethod, ABCMeta
from .exception import CoreException, EmptyValidatorListError, ValueNotValid


if six.PY3:
    long = int
    unicode = str


class ParameterPredicateSyntaxException(CoreException):
    """ParameterPredicateSyntaxException is raised when parameter predicate has syntax errors."""


class ParameterPredicatesParser(object):

    param_name = OneOrMore(
        Regex('[^=, >, \], \[, \,, <, <=, >=, !=]+') + Optional(Regex("\[(0|[1-9][0-9]*|\*|\?)\]"))).setParseAction(lambda x: ''.join(x))('name')  # noqa W605

    param_value_without_quotes = Regex('[^=, >, \], \[, \,, <, <=, >=, !=, "]+')('value')  # noqa W605
    param_value_with_quotes = Literal('"') + OneOrMore(Regex('[^"]+')).setParseAction(lambda x: ' '.join(x))('value') + Literal('"')('quoted')
    param_value = (param_value_without_quotes | param_value_with_quotes)

    operator = Or_((Literal("=regex"), Literal("!=regex"), Literal('>'), Literal('<'),
                   Literal('>='), Literal('<='), Literal('='), Literal('!=')))('operator')
    empty_operator = Literal("=empty")('operator')
    non_empty_operator = Literal("!=empty")('operator')
    empty_value = Empty().setParseAction(lambda x: "")('value')

    predicate_body = Group((param_name + (((empty_operator | non_empty_operator) + empty_value) | (operator + param_value))))('predicate_body')
    predicate_content = Group((Optional(Literal(',')) + predicate_body)).setResultsName('predicates', True)

    grammar = OneOrMore(predicate_content)

    comparators = {
        '>': lambda x, y: x > y,
        '>=': lambda x, y: x >= y,
        '<': lambda x, y: x < y,
        '<=': lambda x, y: x <= y,
        '=': lambda x, y: x == y,
        '!=': lambda x, y: x != y,
        '=regex': lambda x, y: True if re.match(str(y), str(x)) else False,
        '!=regex': lambda x, y: False if re.match(str(y), str(x)) else True,
        '=empty': lambda x, y: not x and x != 0,
        '!=empty': lambda x, y: x or x == 0,
    }

    @classmethod
    def parse(self, parameters_expression):
        """Parse expression."""
        try:
            parsed_expression = self.grammar.parseString(parameters_expression)
        except ParseException as e:
            raise ParameterPredicateSyntaxException("%s in expression: '%s'" % (str(e), parameters_expression))

        predicates = []
        for predicate in parsed_expression.predicates:
            comparator = self.comparators[predicate.predicate_body.operator]
            param_locator = self._extract_location_parts(predicate.predicate_body.name)
            expected_value = predicate.predicate_body.value if predicate.predicate_body.quoted \
                else self._convert_value(predicate.predicate_body.value)
            predicates.append((param_locator, comparator, expected_value))

        return predicates

    @classmethod
    def _extract_location_parts(self, param_name):
        return [re.match(r'(?P<part>[^\[,\]]*)(\[(?P<index>.*)\])*', part).groups()[::2] for part in param_name.split('.')]

    @classmethod
    def _convert_value(self, value):
        converters = [self._to_bool, self._to_int, self._to_float, str]
        for converter in converters:
            try:
                return converter(value)
            except Exception:
                pass
        raise Exception('Can not convert type of: %s' % value)

    @classmethod
    def _to_int(self, value, skip_none=False):
        if value is None and skip_none or isinstance(value, int):
            return value
        if isinstance(value, (six.string_types, six.binary_type)):
            try:
                return int(value)
            except ValueError:
                raise ValueError('Value "{}" is not an integer number representation'.format(str(value)))
        raise Exception('Object "{}" with value "{}" cannot be converted to int'.format(type(value).__name__, str(value)))

    @classmethod
    def _to_float(self, value, skip_none=False):
        if value is None and skip_none or isinstance(value, float):
            return value
        if isinstance(value, ((six.string_types, six.binary_type), int)):
            try:
                return float(value)
            except ValueError:
                raise ValueError('Value "{}" is not a floating point number representation'.format(str(value)))
        raise Exception('Object "{}" with value "{}" cannot be converted to float'.format(type(value).__name__, str(value)))

    @classmethod
    def _to_bool(self, value, skip_none=False):
        if value is None and skip_none or isinstance(value, bool):
            return value
        if isinstance(value, (six.string_types, six.binary_type)):
            return self._str_to_bool(value)
        raise Exception('Object "{}" with value "{}" cannot be converted to bool'.format(type(value).__name__, str(value)))

    @classmethod
    def _str_to_bool(self, value):
        if self._looks_like_true(value):
            value = True
        elif self._looks_like_false(value):
            value = False
        else:
            raise Exception('Value is from out of range. Available values are (not case sensitive): ${True}, ${False}, true, false')
        return value

    @classmethod
    def _looks_like_false(self, value):
        return value.lower().strip() == "false"

    @classmethod
    def _looks_like_true(self, value):
        return value.lower().strip() == "true"


class ObjectValidator(object):

    def __init__(self, parameters):
        self.predicates = ParameterPredicatesParser.parse(parameters) if parameters else []

    def check(self, payload):
        """Check object against parameters predicates."""
        if not payload or not isinstance(payload, dict):
            return False
        return all(self._check_value(locator, comp, expected_value, payload) for locator, comp, expected_value in self.predicates)

    def _check_value(self, param_locator, comparator, expected_value, source, depth=0):
        if depth == len(param_locator):
            return comparator(source, expected_value)

        name, index = param_locator[depth]
        try:
            source = source[name]
            return self._check_values_depending_on_type(param_locator, comparator, expected_value, source, index, depth)
        except (IndexError, KeyError, TypeError):
            return False

    def _check_values_depending_on_type(self, param_locator, comparator, expected_value, source, index, depth):
        if isinstance(source, list):
            return self._check_values_in_list(param_locator, comparator, expected_value, source, index, depth)
        elif isinstance(source, dict):
            depth += 1
            return self._check_value(param_locator, comparator, expected_value, source, depth)
        else:
            return comparator(source, expected_value)

    def _check_values_in_list(self, param_locator, comparator, expected_value, source, index, depth):
        depth += 1
        if index == "*":
            return all(self._check_value(param_locator, comparator, expected_value, s, depth) for s in source)
        elif index == "?":
            return any(self._check_value(param_locator, comparator, expected_value, s, depth) for s in source)
        elif self._is_numeric(index):
            return self._check_value(param_locator, comparator, expected_value, source[int(index)], depth)
        else:
            return comparator(source, expected_value)

    def _is_numeric(self, param):
        if not param:
            return False
        if hasattr(param, 'decode'):
            param = param.decode('ascii')
        if param.isnumeric():
            return True
        return False


class ObjectsValidator(object):

    def __init__(self, parameter_predicates):
        self.validator = ObjectValidator(parameter_predicates)

    def check(self, object_list):
        """Check objects against parameters predicates."""
        if not isinstance(object_list, list):
            return False
        return self._check_objects(object_list)

    def _check_objects(self, object_list):
        raise NotImplementedError


class AnyObjectValidator(ObjectsValidator):

    def _check_objects(self, object_list):
        return any(self.validator.check(obj) for obj in object_list)


class AllObjectsValidator(ObjectsValidator):

    def _check_objects(self, object_list):
        if not object_list:
            return False
        return all(self.validator.check(obj) for obj in object_list)


class NoneObjectsValidator(ObjectsValidator):

    def _check_objects(self, object_list):
        return not any(self.validator.check(obj) for obj in object_list)


class ValidationResult(object):
    """Class for storing value, result, message."""

    def __init__(self, value, result, message):
        """
        :param object value: Validated value.
        :param boolean result: Validation result.
        :param string message: Validation message.

        :return: Validation result.
        :rtype: boolean

        .. code-block:: python

           validation_result = ValidationResult(10, True, 'Is value the number type')
           print validation_result           # will print 'Is value the number type'
        """
        self.value = value
        self.result = result
        self.message = message

    def __str__(self):
        return self.message


@six.add_metaclass(ABCMeta)
class Validator(object):
    """Abstract base validator class."""
    RESULT_MESSAGE_TEMPLATE = "Validating <%s> with result: <%s>. "

    def __init__(self, *args, **kw):
        self.result_message_template = self.__class__.RESULT_MESSAGE_TEMPLATE

    @abstractmethod
    def validate(self, value, *args, **kw):
        """Abstract method to validating value. All classes inherited from base Validator class.
         have to implement this method.

        :param object value: Value to validate.

        :return: Validation result.
        :rtype: ValidationResult
        """

    def check(self, value, *args, **kw):
        """Check if provided value is valid for specific validator.

        :param object value: Value to validate.
        :raises: ValueNotValid in case when validation result is negative.
        """
        validation_result = self.validate(value, *args, **kw)
        if not validation_result.result:
            raise ValueNotValid(validation_result.message)

    def _build_message(self, *args):
        return self.result_message_template % args


def is_string(value):
    """Function checks if value type is string.

    :param value: Value to validate.
    :return: Validation result.
    :rtype: boolean

    .. code-block:: python

       is_string('example_string')    # returns True
       is_string(10)                  # returns False
    """
    return type(value) in (str, unicode)


class IsString(Validator):
    """Validator is checking that value is string type.

    .. code-block:: python

       validation_expression = IsString()
       validation_expression.validate(10)      # returns ValidationResult object
    """
    RESULT_MESSAGE_TEMPLATE = "Is <%s> a string?: %s"

    def __init__(self, *args, **kw):
        super(IsString, self).__init__(*args, **kw)

    def validate(self, value, *args, **kw):
        """Method checks if specified value meet requirements."""
        result = is_string(value)
        message = self._build_message(value, result)
        return ValidationResult(value, result, message)


class IsOneOf(Validator):
    """Validator is checking that value is one of an options.

    .. code-block:: python

       validation_expression = IsOneOf(10, 20, 'test_string, False)
       validation_expression.validate('test_string')       # returns ValidationResult object
    """
    RESULT_MESSAGE_TEMPLATE = "Is <%s> one of [%s]?: %s"

    def __init__(self, *args, **kw):
        super(IsOneOf, self).__init__(*args, **kw)
        self.options = list(args)

    def validate(self, value, *args, **kw):
        """Method checks if specified value meet requirements."""
        result = value in self.options
        message = self._build_message(value, ', '.join(str(o) for o in self.options), result)
        return ValidationResult(value, result, message)


class MultiValidator(Validator):
    """Multi validator is base class for validators which contain sub validators."""

    def __init__(self, *args, **kw):
        """Keyword arguments may contain "chain" parameter and it has to be bool. When is missing the False is taken.
           Parameter "chain" is able to limit validation operation by checking if collected results are enough to
           make pass/fail validation decision.
        """
        super(MultiValidator, self).__init__(*args, **kw)
        self.sub_validators = list(args)
        if not self.sub_validators:
            raise EmptyValidatorListError('Validator list is empty')
        self.chain = kw.get('chain', False)

    def _build_message(self, result, results):
        message = ""
        for child in results:
            message += "\n" + "\n".join(map(lambda s: "  %s" % s, str(child).split("\n")))

        message = super(MultiValidator, self)._build_message(result, message)
        return message


class And(MultiValidator):
    """Validator to build validation expression with Validator objects and 'and' operator.

    .. code-block:: python

       validator = And(IsNumber(), InRange(0, 10)
       validator.validate(2)                 # returns True
       validator.validate(11)                # returns False
       validator.validate('test_string_')    # returns False
    """

    RESULT_MESSAGE_TEMPLATE = "Are all of the following conditions fulfilled?: %s%s"

    def __init__(self, *args, **kw):
        """Keyword arguments may contain "chain" parameter and it has to be bool. When is missing the False is taken.
           Parameter "chain" will fail validation after first False result.
        """
        super(And, self).__init__(*args, **kw)

    def _validate(self, value):
        result = True
        results = []
        for v in self.sub_validators:
            r = v.validate(value)
            results.append(r)
            if not r.result:
                result = False
                if self.chain:
                    break
        return result, results

    def validate(self, value, *args, **kw):
        """Method checks if specified value meet requirements."""
        result, results = self._validate(value)
        message = self._build_message(result, results)
        return ValidationResult(value, result, message)


class Or(MultiValidator):
    """Or validator is for build validation expression with Validator objects and 'or' operator.

    .. code-block:: python

       validator = Or(InRange(0, 10), InRange(20, 30))
       print validator.validate(2)   # returns True
       print validator.validate(11)  # returns False
       print validator.validate(25)  # returns True
    """

    RESULT_MESSAGE_TEMPLATE = "Is any of the following conditions fulfilled?: %s%s"

    def __init__(self, *args, **kw):
        """Keyword arguments may contain "chain" parameter and it has to be bool. When is missing the False is taken.
           Parameter "chain" will pass validation after first True result.
        """
        super(Or, self).__init__(*args, **kw)

    def _validate(self, value):
        result = False
        results = []
        for v in self.sub_validators:
            r = v.validate(value)
            results.append(r)
            if not result and r.result:
                result = True
                if self.chain:
                    break

        return result, results

    def validate(self, value, *args, **kw):
        """Method checks if specified value meet requirements."""
        result, results = self._validate(value)
        message = self._build_message(result, results)
        return ValidationResult(value, result, message)


def is_instance(value, classinfo):
    """Function checks that value object is an instance of the classinfo.

    :param value: Value to validate.
    :param classinfo: Class object to be compared with value argument.

    :return: Validation result.
    :rtype: boolean

    .. code-block:: python

       is_instance('example_string', str)    # returns True
       is_instance(1, str)                   # returns False

    """
    return isinstance(value, classinfo)


class IsInstance(Validator):
    """Validator is checking that value object is an instance of a class.

    .. code-block:: python

       validation_expression = IsInstance()
       validation_expression.validate(10, int)        # returns ValidationResult object
    """
    err_msg = "Is <%s> instance of <%s>?: %s"

    def __init__(self, classinfo, *args, **kw):
        """
        :param classinfo: Class instance object.
        """
        super(IsInstance, self).__init__(*args, **kw)
        self.classinfo = classinfo

    def validate(self, value, *args, **kw):
        """Method checks if specified value meet requirements."""
        result = is_instance(value, self.classinfo)
        message = IsInstance.err_msg % (value, self.classinfo, result)
        return ValidationResult(value, result, message)


class Assert(Validator):
    """Generic validator which is using function to validate value.

    .. code-block:: python

       validation_expression = Assert(lambda x: isString(x), 'Value is not correct')
       validation_expression.validate('test_string')       # returns ValidationResult object
    """

    def __init__(self, func, err_msg, *args, **kw):
        """
        :param func: Validation function.
        :param string err_msg: Message which will be add when validation fail.
        """
        super(Assert, self).__init__(*args, **kw)
        self.func = func
        self.err_msg = err_msg

    def validate(self, value, *args, **kw):
        """Method checks if specified value meet requirements."""
        result = self.func(value, *args, **kw)
        message = self._build_message(value, result) + (self.err_msg if not result else '')
        return ValidationResult(value, result, message)


class Matches(And):
    """Validator is checking that value match regex.

    .. code-block:: python

       validation_expression = Matches(r"\w+")
       validation_expression.validate('test_string ')     # returns ValidationResult object
    """  # noqa W605

    def __init__(self, regex, *args, **kw):
        """
        :param str regex: Regex using in string matching.
        """
        super(Matches, self).__init__(IsString(),
                                      Assert(lambda x: bool(match(regex, x)), "Value doesn't match"),
                                      chain=True,
                                      *args,
                                      **kw)
        self.regex = regex


def is_in_range(value, from_value, to_value):
    """
    Function checks that value is between specified range.

    :param number value: Value to validate.
    :param number from_value: Beginning of range.
    :param number to_value: Ending of range.

    :return: Validation result.
    :rtype: boolean

    .. code-block:: python

       is_in_range(10, 0, 20)      # returns True
       is_in_range(10, 0, 10)      # returns False
    """
    if value is None or isinstance(value, str):
        output = False
    else:
        output = value >= from_value and value <= to_value
    return output


class InRange(Validator):
    """Validator is checking that value is in specified range.

    .. code-block:: python

       validation_expression = InRange(0, 20)
       validation_expression.validate(10)      # returns ValidationResult object
    """
    RESULT_MESSAGE_TEMPLATE = "Is <%s> between <%s> and <%s>?: %s"

    def __init__(self, from_value, to_value, *args, **kw):
        """
        :param number from_value: Beginning of range.
        :param number to_value: Ending of range.
        """
        super(InRange, self).__init__(*args, **kw)
        self.from_value = from_value
        self.to_value = to_value

    def validate(self, value, *args, **kw):
        """Method checks if specified value meet requirements."""
        result = is_in_range(value, self.from_value, self.to_value)
        message = self._build_message(value, self.from_value, self.to_value, result)
        return ValidationResult(value, result, message)
